const app=document.querySelector('#app');
const logo='<img class="logo" src="assets/logo.svg" alt="EINTRIKOT">';
const band='<div class="ribbon" aria-hidden="true"></div>';
const button=(text,href,cls='')=>`<a class="button ${cls}" href="${href}">${text}</a>`;
const navItems=[['portal','Portal'],['mitglieder','Mitglieder'],['mitglieder-news','Vereinsinfos'],['services','Service']];
function header(){return `<header class="header"><a href="#website" aria-label="EINTRIKOT Startseite">${logo}</a><button class="menu-toggle" aria-expanded="false" aria-controls="public-nav" aria-label="Menü öffnen">☰</button><nav class="nav" id="public-nav" aria-label="Hauptnavigation"><a href="#verein">Der Verein</a><a href="#engagement">Engagement</a><a href="#news">News</a><a href="#partner">Unterstützen</a>${button('Mitglied werden','#beitritt','white')}${button('Anmelden','#login')}</nav></header>`}
function footer(){return `<footer class="footer"><div>${logo}<p>Das Netzwerk der Nationalteams.</p><a href="mailto:info@eintrikot.de">info@eintrikot.de</a><small>EINTRIKOT e. V. · Gemeinnütziger Verein</small></div><nav aria-label="Mehr über EINTRIKOT"><a href="#verein">Der Verein</a><a href="#engagement">Engagement</a><a href="#news">News</a><a href="#partner">Unterstützen</a></nav><nav aria-label="Rechtliches"><a href="#kontakt">Kontakt</a><a href="#impressum">Impressum</a><a href="#datenschutz">Datenschutz</a></nav></footer>`}
function baseWebsite(){return `${header()}<main id="main"><section class="hero"><div class="band" aria-hidden="true"></div><div class="hero-content"><h1>Das Netzwerk<br>der Nationalteams.</h1><p>Wir verbinden Hockey-Nationalspielerinnen und Nationalspieler – von den Jugendnationalteams über die Damen und Herren bis zu den Ehemaligen.</p><div class="actions">${button('Mitglied werden','#beitritt','white')}${button('Anmelden','#login')}</div></div></section><section class="section intro" id="club"><h2>Ein gemeinsames Trikot.<br>Eine bleibende Verbindung.</h2><div><p>EINTRIKOT verbindet aktuelle und ehemalige Hockey-Nationalspielerinnen und Nationalspieler aller Generationen.</p><p>Wir schaffen Begegnungen, teilen Erfahrungen und geben der nächsten Generation etwas weiter. Auf dem Platz. Und darüber hinaus.</p></div></section><section class="section phases" id="konzept"><h2>Ein Trikot. Drei Lebensphasen.</h2><div class="phase-grid"><article><span class="index">01</span><h3>Rein ins Trikot.</h3><p>Schon als Mitglied eines Jugendnationalteams gehörst du dazu. Gemeinsam wachsen, Erfahrungen sammeln und Verbindungen knüpfen.</p></article><article><span class="index">02</span><h3>Im Trikot.</h3><p>Gemeinsame Spiele. Große Momente. Erfahrungen, die prägen – und über Mannschaften und Jahrgänge hinweg verbinden.</p></article><article><span class="index">03</span><h3>Raus aus dem Trikot.</h3><p>Die aktive Zeit endet. Die Verbindung bleibt. Wir halten sie lebendig und öffnen neue Wege, sich einzubringen.</p></article></div>${band}</section><section class="section" id="wirkung"><div class="impact-head"><h2>Was wir gemeinsam möglich machen.</h2><p>Unser Netzwerk verbindet Erfahrung mit dem Wunsch, den Hockeysport weiterzubringen.</p></div><div class="impact-row"><span>01</span><h3>Nachwuchs fördern</h3><p>Jungen Talenten Möglichkeiten eröffnen und ihre Entwicklung begleiten.</p></div><div class="impact-row"><span>02</span><h3>Erfahrung weitergeben</h3><p>Wissen aus Nationalteams, Turnieren und dem Leben nach dem Leistungssport teilen.</p></div><div class="impact-row"><span>03</span><h3>Begegnungen schaffen</h3><p>Spielerinnen und Spieler verschiedener Generationen wieder zusammenbringen.</p></div><p class="only-demo">Konkrete Förderprojekte und bestätigte Kennzahlen ergänzen wir nach redaktioneller Freigabe.</p></section><section class="section quote"><h2>Ein Trikot endet nicht mit dem letzten Spiel.</h2><p>Was bleibt, sind die Menschen. Die gemeinsamen Erinnerungen. Und die Möglichkeit, zusammen etwas zu bewegen.</p></section><section class="section" id="news"><div class="news-head"><h2>Aus dem Club.</h2><a class="text-link" href="#artikel">Beitrag lesen ↗</a></div><article class="story"><div class="story-art" aria-hidden="true">${band}</div><div><span class="micro">13. Juli 2026</span><h3>Neue Website live</h3><p>Ein neuer Ort für unsere Verbindung.</p><a class="text-link" href="#artikel">Weiterlesen ↗</a></div></article><p class="only-demo">Bestehender Beitrag als Gestaltungsreferenz; Text wird vor Veröffentlichung geprüft.</p></section><section class="section partners" id="partner"><h2>Gemeinsam für den deutschen Hockeyleistungssport.</h2><p>Hier bekommen die Partner von EINTRIKOT ihren Platz.</p><p class="only-demo">Partnerlogos und persönliche Stimmen folgen mit Freigabe und Originalmaterial.</p></section><section class="section closing"><div class="closing-content"><h2>Dein Trikot.<br>Deine Verbindung.</h2><p>Bleib Teil des Netzwerks. Gestalte mit, was als Nächstes kommt.</p>${button('Mitglied werden','#beitritt','solid')}<p><small>Beitritt über MeinVerein.</small></p></div>${band}</section></main>${footer()}`}
function baseShell(content,page){return `<div class="shell"><aside class="sidebar"><a href="#website">${logo}</a><nav class="side-nav" aria-label="Mitgliederbereich">${navItems.map(([id,t])=>`<a href="#${id}" class="${page===id?'active':''}">${t}</a>`).join('')}</nav><div class="side-bottom"><a href="#website">Zur öffentlichen Website ↗</a></div></aside><div><div class="mobile-brand"><a href="#website">${logo}</a><a class="text-link" href="#services">Service</a></div>${accountMenu()}<main class="portal-main" id="main">${content}</main></div><nav class="bottom-nav" aria-label="Mobile Mitgliedernavigation">${[['portal','Portal'],['mitglieder','Mitglieder'],['services','Service']].map(([id,t])=>`<a class="${id===page?'active':''}" href="#${id}">${t}</a>`).join('')}</nav></div>`}
const services=()=>[['stammdaten','Stammdaten ändern'],['foerderbeitrag','EINTRIKOT zusätzlich fördern'],['event','Für ein Event anmelden'],['foerderidee','Förderidee einreichen'],['mitarbeit','Ich möchte mich einbringen'],['kontakt','Vorstand kontaktieren']].map(([id,t])=>`<a class="service-link" href="#${id}">${t}<span aria-hidden="true">↗</span></a>`).join('');
function dashboard(){return shell(`<section class="welcome"><h1>Schön, dass du da bist.</h1><p>Dein Platz bei EINTRIKOT.</p>${band}</section><div class="portal-grid"><div><h2>Aus der Community</h2><article class="news-piece"><h3>Willkommen im neuen Portal</h3><p>Hier entsteht dein Treffpunkt für News, Termine und gemeinsame Vorhaben.</p><a class="text-link" href="#profil">Dein Profil prüfen ↗</a></article><section class="portal-section"><h2>Deine nächsten Termine</h2><p class="empty">Sobald Termine feststehen, findest du sie hier.</p></section></div><div><h2>So kannst du mitmachen</h2>${services()}<section class="portal-section"><h2>Deine Anfragen</h2><p class="empty">In dieser Vorschau sind noch keine Anfragen hinterlegt.</p></section></div></div>`,'portal')}
function visibility(id){return `<select class="visibility" name="${id}_visibility" aria-label="Sichtbarkeit: ${id}"><option value="private">Nur ich</option><option value="members">Mitglieder</option><option value="hidden">Nicht anzeigen</option></select>`}
function field(id,label,type='text',full=false){return `<label class="field ${full?'full':''}"><span class="field-head"><span>${label}</span>${visibility(id)}</span>${type==='textarea'?`<textarea aria-label="${label}" name="${id}"></textarea>`:`<input aria-label="${label}" name="${id}" type="${type}" ${type==='number'?'min="0"':''}>`}</label>`}
function station(){return `<div class="station"><label class="field">Rolle<select name="role[]"><option>Spielerin / Spieler</option><option>Schiedsrichterin / Schiedsrichter</option><option>Staff</option><option>Delegationsleitung</option><option>Weitere Rolle</option></select></label><label class="field">Team / Organisation<input name="organisation[]" placeholder="z. B. DHB"></label><label class="field">Altersklasse<input name="age_class[]" placeholder="z. B. U21"></label><label class="field">Von<input name="from[]" type="number" min="1900" max="2100" placeholder="Jahr"></label><label class="field">Bis<input name="to[]" type="number" min="1900" max="2100" placeholder="Jahr"></label></div>`}
function profile(){return shell(`<div class="profile-title"><h1>Dein Weg. Dein Profil.</h1><p>Du entscheidest, was du teilst.</p><p class="only-demo">Alle Angaben sind freiwillig. In dieser Vorschau bitte nur erfundene Daten verwenden. Speichern gilt nur für diese Sitzung.</p></div><form class="profile-form" id="profile-form"><section class="form-section"><h2>Über dich</h2><div class="form-grid"><label class="field"><span class="field-head"><span>Profilbild</span>${visibility('bild')}</span><img class="avatar-preview" id="avatar" alt="Profilbild-Vorschau" hidden><input type="file" id="avatar-file" accept="image/png,image/jpeg,image/webp"></label>${field('club','Aktueller Verein / Vereins-Team')}${field('city','Wohnort')}${field('region','Region / Bundesland')}<label class="field">Geburtsdatum<input type="date" name="birthday" id="birthday" max="${localDate()}" min="1900-01-01"><small>Bleibt privat. Im Mitgliederprofil erscheint nur dein Alter, wenn du es freigibst.</small></label><div class="field"><span class="field-head"><span>Alter im Mitgliederprofil</span>${visibility('age')}</span><output id="age-preview">Noch kein Geburtsdatum angegeben.</output></div></div></section><section class="form-section"><h2>Hockey-Lebenslauf</h2><div class="form-grid" style="margin-bottom:25px"><label class="field"><span class="field-head"><span>Team</span>${visibility('team')}</span><select name="team" aria-label="Team"><option value="">Keine Angabe</option><option>Damen</option><option>Herren</option></select></label><label class="field"><span class="field-head"><span>Trikotphase</span>${visibility('phase')}</span><select name="phase" aria-label="Trikotphase"><option value="">Keine Angabe</option><option>Aktuell</option><option>Ehemalig</option></select></label></div>${field('hockey','Ein besonderer Moment oder eine Geschichte','textarea',true)}<div class="field-head" style="margin-top:25px"><span>Deine Stationen</span>${visibility('stationen')}</div><div id="stations">${station()}</div><button class="button" id="add-station" type="button">+ Station hinzufügen</button><div class="form-grid" style="margin-top:30px">${field('caps','Länderspiele gesamt','number')}${field('youth_caps','Länderspiele nach Altersklasse')}</div></section><section class="form-section"><h2>Abseits des Platzes</h2><div class="form-grid">${field('hobbies','Hobbys')}${field('other_sport','Sport neben Hockey')}</div></section><details class="form-section profile-extra"><summary>Beruf & Ausbildung</summary><div class="form-grid">${field('job','Beruf / Position')}${field('employer','Unternehmen / Organisation')}${field('industry','Branche')}${field('employment','Beruflicher Status')}${field('university','Hochschule / Ausbildungsstätte')}${field('subject','Studiengang / Ausbildung')}${field('degree','Abschluss')}${field('education_period','Zeitraum der Ausbildung')}</div></details><details class="form-section profile-extra"><summary>Interessen & Mitmachen</summary><div class="form-grid">${field('mentoring','Mentoring: anbieten oder suchen?')}${field('support','Unterstützung: Events, Sponsoring, Karrieretipps, Praktika oder Jobs','textarea')}</div>${field('contribution','So möchte ich mich bei EINTRIKOT einbringen','textarea',true)}</details><section class="form-section"><h2>EINTRIKOT zusätzlich fördern</h2><label class="field">Möchtest du zusätzlich zum Mitgliedsbeitrag jährlich spenden?<select name="funding_interest"><option value="">Noch offen</option><option value="yes">Ja, ich möchte zusätzlich fördern</option><option value="no">Derzeit nicht</option></select></label><p>Deine Auswahl ist unverbindlich. Betrag und Beginn bestätigst du in einer separaten Anfrage.</p><a class="text-link" href="#foerderbeitrag" id="prepare-funding">Förderanfrage vorbereiten ↗</a></section><section class="form-section"><h2>In Verbindung bleiben</h2><label class="check"><input type="checkbox" name="birthday_notice"><span>Mein Geburtstag darf mit meinem Namen in den internen Vereinsinfos erscheinen. Das Geburtsjahr wird nicht angezeigt.</span></label><label class="check"><input type="checkbox" name="newsletter" checked><span>EINTRIKOT-Newsletter erhalten<br><small>Du kannst diese Einstellung jederzeit ändern.</small></span></label></section><div class="save-bar"><button class="button solid" type="submit">Änderungen speichern</button><button class="button" type="reset">Zurücksetzen</button></div></form>`,'profil')}
function newsletter(){return `${header()}<main id="main" class="newsletter-page"><p class="preview-note">Newsletter-Gestaltung · Beispielausgabe, kein Versand. Die Opt-out-Voreinstellung bleibt vor Echtversand zu prüfen.</p><div class="email"><div class="email-top">EINTRIKOT · Newsletter-Vorschau</div><header class="email-header">${logo}<h1>Was uns verbindet.</h1><p>News aus unserem Hockey-Netzwerk.</p>${band}</header><div class="email-body"><article><span class="micro">Aus dem Club</span><h2>Unser neuer Treffpunkt</h2><p>Dein Profil, News und Termine: Das neue Mitgliederportal bringt unsere Verbindung an einen Ort.</p><a class="text-link" href="#portal">Zum Mitgliederportal ↗</a></article><article><span class="micro">Gemeinsam etwas bewegen</span><h2>Raum für die nächste Generation.</h2><p>Hier erscheint das nächste freigegebene Förderprojekt – mit konkreten Einblicken und Möglichkeiten, sich einzubringen.</p></article><article><span class="micro">Wir sehen uns</span><h2>Neue Begegnungen. Bekannte Gesichter.</h2><p>Die nächsten bestätigten Termine ergänzen wir vor dem Versand.</p><a class="text-link" href="#termine">Zu den Terminen ↗</a></article>${button('Mein Profil ansehen','#profil','solid')}</div><footer class="email-footer"><strong>EINTRIKOT e. V.</strong><p>[Vereinsanschrift nach Prüfung]</p><a href="#profil">Newsletter-Einstellungen</a><a href="#abmelden">Newsletter abbestellen</a><a href="#impressum">Impressum</a><a href="#datenschutz">Datenschutz</a></footer></div><p class="preview-note">Entwurf → Testversand → Vorstandsfreigabe → Versand.<br>Betreff: Neues aus deinem EINTRIKOT-Netzwerk</p></main>`}
function login(reset=false){return `${header()}<main id="main" class="auth"><div class="auth-inner"><h1>${reset?'Passwort vergessen?':'Willkommen zurück.'}</h1><p>${reset?'Wir senden dir einen Link, mit dem du dein Passwort neu festlegen kannst.':'Dein Zugang zum EINTRIKOT-Mitgliederbereich.'}</p><form id="auth-form"><label class="field">E-Mail-Adresse<input type="email" required autocomplete="off" placeholder="test@example.com"></label>${reset?'':'<label class="field">Passwort<input type="password" required autocomplete="off"></label>'}<button class="button solid">${reset?'Link anfordern':'Anmelden'}</button></form><a class="text-link" href="#${reset?'login':'passwort'}">${reset?'Zurück zur Anmeldung':'Passwort vergessen?'}</a><p class="only-demo">Gestaltungsvorschau: keine Anmeldung und kein E-Mail-Versand. Bitte keine echten Zugangsdaten eingeben.</p>${button('Portal-Vorschau öffnen','#portal')}</div></main>${footer()}`}
function contact(page){const title={kontakt:'Deine Nachricht an den Vorstand',foerderidee:'Deine Idee für den Hockeysport',mitarbeit:'Was möchtest du einbringen?'}[page];return shell(`<div class="profile-title"><h1>${title}</h1><p>Wir freuen uns auf deinen Impuls.</p></div><form class="contact-form" id="service-form"><label class="field">Betreff<input required name="subject" maxlength="160"></label><label class="field">Deine Nachricht<textarea required name="message" minlength="10" maxlength="4000"></textarea></label><p class="only-demo">Vorschau: Es wird keine Anfrage gespeichert oder verschickt.</p><button class="button solid">Anfrage prüfen</button></form>`,page==='kontakt'?'kontakt':'services')}
function other(page){if(page==='stammdaten')return masterDataPage();if(page==='kalender')return calendarPage();if(page==='protokoll')return ['board','admin'].includes(previewRole)?shell(`<a class="text-link" href="#admin">← Verwaltung</a><h1>Änderungsprotokoll.</h1><p class="only-demo">Sitzungsprotokoll. In WordPress eigene geschützte Seite für Vorstand und Admin.</p><div id="audit-list">${auditMarkup()}</div>`,'admin'):shell('<h1>Geschützter Bereich</h1><p>Nur für Vorstand und Admin.</p>','portal');if(page==='mitglieder-news')return clubInfos();if(page==='news')return newsArchive();if(page==='partner')return partnerPage();if(page==='engagement')return engagementPage();if(page.startsWith('beitrag-'))return newsArticle(page);if(page==='foerderbeitrag')return fundingPage();if(page==='mitglieder')return directory();if(page==='verein')return association();if(page==='menschen')return people();if(page==='redaktion')return editorial();if(page==='admin')return administration();if(page.startsWith('mitglied-'))return memberDetail(page);if(page==='services')return shell(`<h1>Service.</h1><h2>Mitmachen & Kontakt</h2>${services()}<section class="portal-section"><h2>Gut zu wissen</h2><a class="service-link" href="#dokumente">Dokumente <span>↗</span></a></section>`,'services');if(page==='termine'||page==='event')return shell('<h1>Wir sehen uns.</h1><p class="empty">Sobald Veranstaltungen freigegeben sind, erscheinen hier Termine und Anmeldemöglichkeiten.</p>','termine');if(page==='dokumente')return shell('<h1>Gut zu wissen.</h1><p>Dokumente für unsere Mitglieder.</p><p class="empty">Die geschützte Dokumentenablage wird in WordPress angebunden. In dieser Vorschau sind keine Dateien hinterlegt.</p>','dokumente');if(page==='mitglieder-news')return shell('<h1>Vereinsinfos.</h1><p>Interne Mitteilungen, Einladungen und Organisatorisches für unsere Mitglieder.</p><article class="news-piece"><h2>Willkommen im neuen Portal</h2><p>Prüfe dein Profil und entscheide, welche Angaben du teilen möchtest.</p><a class="text-link" href="#profil">Mein Profil ↗</a></article>','mitglieder-news');if(page==='artikel')return `${header()}<main class="section" id="main"><span class="micro">13. Juli 2026 · Gestaltungsreferenz</span><h1>Neue Website live</h1><p>Ein neuer Ort für unsere Verbindung.</p><p>Der vollständige Originalbeitrag wird aus WordPress übernommen und redaktionell geprüft.</p><a class="text-link" href="#news">Zurück zu den News</a></main>${footer()}`;return website()}
function showNotice(title,text){document.querySelector('#notice-title').textContent=title;document.querySelector('#notice-text').textContent=text;document.querySelector('#notice').showModal()}
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),4000)}
let savedProfile=null;let current='';
const anchors=['club','konzept','wirkung'];
function render(){const route=location.hash.slice(1)||'website';if(route==='main'){document.querySelector('main')?.focus();return}if(['beitritt','impressum','datenschutz','abmelden'].includes(route)){if(!current){app.innerHTML=website();current='website';bind()}const notices={beitritt:['Mitglied werden','Der Beitritt führt später direkt zum freigegebenen MeinVerein-Antrag. Der verbindliche Link wird noch hinterlegt.'],impressum:['Impressum','Die geprüften Angaben werden vor Veröffentlichung übernommen.'],datenschutz:['Datenschutz','Die Datenschutzhinweise werden vor Veröffentlichung fachlich geprüft und ergänzt.'],abmelden:['Newsletter abbestellen','In der produktiven E-Mail wird das Abonnement über einen persönlichen Abmeldelink beendet. In dieser Vorschau erfolgt keine Änderung.']};showNotice(...notices[route]);history.replaceState(null,'','#'+current);return}
const page=anchors.includes(route)?'website':route;app.innerHTML=page==='website'?website():page==='portal'?dashboard():page==='profil'?profile():page==='newsletter'?restrictedNewsletter():page==='login'||page==='passwort'?login(page==='passwort'):['kontakt','foerderidee','mitarbeit'].includes(page)?contact(page):other(page);current=page;document.title=`EINTRIKOT — ${page==='website'?'Das Netzwerk der Nationalteams':page==='profil'?'Mein Profil':page==='newsletter'?'Newsletter':'Mitgliederportal · Vorschau'}`;document.querySelectorAll('.review a').forEach(a=>a.classList.toggle('active',a.hash==='#'+page));bind();bindNew();if(anchors.includes(route))requestAnimationFrame(()=>document.getElementById(route)?.scrollIntoView());else window.scrollTo(0,0)}
function bind(){document.querySelector('.menu-toggle')?.addEventListener('click',e=>{const open=document.querySelector('.nav').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',open);e.currentTarget.setAttribute('aria-label',open?'Menü schließen':'Menü öffnen')});document.querySelector('#add-station')?.addEventListener('click',()=>document.querySelector('#stations').insertAdjacentHTML('beforeend',station()));const form=document.querySelector('#profile-form');if(form){if(savedProfile){const count=savedProfile.filter(([n])=>n==='age_class[]').length;for(let i=1;i<count;i++)document.querySelector('#stations').insertAdjacentHTML('beforeend',station());const indexes={};for(const [name,value]of savedProfile){const nodes=[...form.elements].filter(el=>el.name===name);const index=indexes[name]||0;if(nodes[index]){if(nodes[index].type==='checkbox')nodes[index].checked=value==='on';else nodes[index].value=value}indexes[name]=index+1}form.elements.newsletter.checked=savedProfile.some(([n])=>n==='newsletter')}
form.addEventListener('submit',e=>{e.preventDefault();savedProfile=[...new FormData(form)].filter(([,v])=>typeof v==='string');toast('Vorschau: Profil für diese Sitzung gespeichert.')});form.addEventListener('reset',()=>{savedProfile=null;toast('Vorschau-Eingaben zurückgesetzt.')});document.querySelector('#avatar-file').addEventListener('change',e=>{const f=e.target.files[0];if(!f)return;if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>5*1024*1024){showNotice('Bild nicht geeignet','Bitte wähle ein JPG-, PNG- oder WebP-Bild bis 5 MB.');e.target.value='';return}const img=document.querySelector('#avatar');img.src=URL.createObjectURL(f);img.hidden=false})}
document.querySelector('#auth-form')?.addEventListener('submit',e=>{e.preventDefault();e.target.reset();showNotice('Zugangsprozess als Vorschau','Der echte Zugang mit Einladung, Passwortvergabe und Reset wird über Ultimate Member angebunden. Es wurden keine Zugangsdaten übertragen.')});document.querySelector('#service-form')?.addEventListener('submit',e=>{e.preventDefault();showNotice('Deine Anfrage ist vorbereitet','Die Eingaben erfüllen die Anforderungen. In dieser lokalen Vorschau erfolgt kein Versand und keine Speicherung im Vereinsbackend.')})}
document.querySelectorAll('.close,.close-dialog').forEach(b=>b.addEventListener('click',()=>document.querySelector('#notice').close()));window.addEventListener('hashchange',render);

// Local role previews demonstrate navigation, never authorization.
let previewRole='member';
const metrics={members:201,donations:12750,generations:5};
const metricLabels={members:'Mitglieder',donations:'Spendenaufkommen (€)',generations:'Generationen im Trikot'};
const canEdit=()=>['editor','board','admin'].includes(previewRole);
const sampleMembers=[
{id:'a',city:'Hamburg',cityVisibility:'members',name:'Testprofil A',team:'Damen',age:'U18',phase:'Aktuell',club:'Testverein Nord',job:'Schule',hobbies:'Musik'},
{id:'b',city:'Köln',cityVisibility:'members',name:'Testprofil B',team:'Herren',age:'U21',phase:'Aktuell',club:'Testverein Süd',job:'Studium',hobbies:'Reisen'},
{id:'c',city:'Berlin',cityVisibility:'members',name:'Testprofil C',team:'Damen',age:'A-Nationalteam',phase:'Aktuell',club:'Testverein Nord',job:'Sport',hobbies:'Lesen'},
{id:'d',city:'Düsseldorf',cityVisibility:'members',name:'Testprofil D',team:'Herren',age:'A-Nationalteam',phase:'Ehemalig',club:'Testverein West',job:'Architektur',hobbies:'Musik'},
{id:'e',city:'München',cityVisibility:'members',name:'Testprofil E',team:'Damen',age:'A-Nationalteam',phase:'Ehemalig',club:'Testverein Süd',job:'Medizin',hobbies:'Laufen'},
{id:'f',city:'Hamburg',cityVisibility:'members',name:'Testprofil F',team:'Herren',age:'U18',phase:'Aktuell',club:'Testverein West',job:'Schule',hobbies:'Reisen'}
];
const audit=[];
let directoryFilters={query:'',team:'',age:'',phase:'',club:'',job:'',hobbies:''};
function esc(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function icon(type){const shapes={growth:'<path d="M12 21V10M12 15C4 15 3 9 3 5c6 0 9 3 9 8M12 12c0-6 4-9 9-9 0 6-3 9-9 9"/>',share:'<path d="M4 4h6c2 0 2 1 2 2v15c0-2-2-3-4-3H4zm16 0h-6c-2 0-2 1-2 2v15c0-2 2-3 4-3h4z"/>',people:'<circle cx="8" cy="8" r="3"/><circle cx="18" cy="9" r="2"/><path d="M2 21v-3a6 6 0 0 1 12 0v3m2-7a4 4 0 0 1 6 4v3"/>'};return `<svg viewBox="0 0 24 24" width="32" height="32" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${shapes[type]}</svg>`}
function website(){let html=baseWebsite();
html=html.replace('<section class="section intro"',`<section class="metrics" aria-label="EINTRIKOT in Zahlen"><div><strong>${metrics.members.toLocaleString("de-DE")}</strong><span>Mitglieder</span></div><div><strong>${metrics.donations.toLocaleString("de-DE")} €</strong><span>Spendenaufkommen</span></div><div><strong>${totalCaps()===null?'—':totalCaps().toLocaleString("de-DE")}</strong><span>Länderspiele unserer Mitglieder</span><small>${totalCaps()===null?'Mitgliederdaten folgen':'Vorschau · erfasste Testangaben'}</small></div><div><strong>${metrics.generations.toLocaleString("de-DE")}</strong><span>Generationen im Trikot</span></div></section><section class="section intro"`);
html=html.replace('<span class="index">01</span>','<span class="phase-name">Jugendnationalteams</span>').replace('<span class="index">02</span>','<span class="phase-name">Aktive Nationalteams</span>').replace('<span class="index">03</span>','<span class="phase-name">Nach der aktiven Zeit</span>');
html=html.replace('<span>01</span><h3>Nachwuchs fördern',icon('growth')+'<h3>Nachwuchs fördern').replace('<span>02</span><h3>Erfahrung weitergeben',icon('share')+'<h3>Erfahrung weitergeben').replace('<span>03</span><h3>Begegnungen schaffen',icon('people')+'<h3>Begegnungen schaffen');
html=html.replace('<p class="only-demo">Konkrete Förderprojekte und bestätigte Kennzahlen ergänzen wir nach redaktioneller Freigabe.</p>','<a class="text-link" href="#engagement">Unser Engagement kennenlernen ↗</a>');
html=html.replace('<section class="section quote">',`<section class="section voices"><div class="section-heading"><h2>Ein Netzwerk.<br>Viele Perspektiven.</h2><p>Was Mitglieder an EINTRIKOT schätzen.</p></div><div class="voice-grid"><article><div class="portrait-placeholder">Porträt folgt</div><div><span class="phase-name">Jugendnationalteam</span><blockquote>Hier bekommt die persönliche Stimme eines jungen Mitglieds ihren Platz.</blockquote><p>Name und freigegebenes Originalzitat folgen.</p></div></article><article><div class="portrait-placeholder">Porträt folgt</div><div><span class="phase-name">Aktiv oder nach der Karriere</span><blockquote>Hier erzählt ein Mitglied, was die Verbindung über die aktive Zeit hinaus bedeutet.</blockquote><p>Name und freigegebenes Originalzitat folgen.</p></div></article></div><p class="only-demo">Gestaltungsplätze, keine erfundenen Mitgliederzitate.</p></section><section class="section quote">`);
html=html.replace('<p>Hier bekommen die Partner von EINTRIKOT ihren Platz.</p><p class="only-demo">Partnerlogos und persönliche Stimmen folgen mit Freigabe und Originalmaterial.</p>',`<p>Als Partner, Sponsor oder mit einer Spende kannst du unsere Vereinsarbeit unterstützen.</p><div class="support-links"><a href="#unterstuetzen">Partner werden ↗</a><a href="#unterstuetzen">Sponsoring ↗</a><a href="#spenden">Spenden ↗</a></div><p class="only-demo">Partnerlogos folgen nach Freigabe.</p>`);
html=html.replace('Wir schaffen Begegnungen, teilen Erfahrungen und geben der nächsten Generation etwas weiter. Auf dem Platz. Und darüber hinaus.</p>','Wir schaffen Begegnungen, teilen Erfahrungen und geben der nächsten Generation etwas weiter. Auf dem Platz. Und darüber hinaus.</p><a class="text-link" href="#verein">Mehr über den Verein ↗</a>');
const start=html.indexOf('<section class="section" id="news">');const end=html.indexOf('<section class="section partners"',start);if(start!==-1&&end!==-1)html=html.slice(0,start)+`<section class="section"><div class="news-head"><h2>Aus dem Netzwerk.</h2><a class="text-link" href="#news">Alle News ↗</a></div>${newsCards(newsPosts.slice(0,3))}<p class="only-demo">Redaktionelle Beispielplätze. Originalbeiträge folgen aus WordPress.</p></section>`+html.slice(end);const ps=html.indexOf('<section class="section partners"');const pe=html.indexOf('<section class="section closing"',ps);if(ps!==-1)html=html.slice(0,ps)+thanks()+html.slice(pe);html=html.replace('<section class="section phases"',vision2030()+'<section class="section phases"');return html}
function shell(content,page){let html=baseShell(content,page);if(canEdit())html=html.replace('</nav><div class="side-bottom">',`${[['redaktion','Redaktion'],...(['board','admin'].includes(previewRole)?[['admin','Verwaltung']]:[])].map(([id,label])=>`<a href="#${id}" class="role-nav ${page===id?'active':''}">${label}</a>`).join('')}</nav><div class="side-bottom">`);if(['kontakt','foerderidee','mitarbeit','event','dokumente'].includes(location.hash.slice(1)))html=html.replace('<main class="portal-main" id="main">','<main class="portal-main" id="main"><a class="text-link service-back" href="#services">← Service</a>');return html}

function association(){return `${header()}<main id="main"><section class="section page-intro"><span class="micro">EINTRIKOT e. V.</span><h1>Ein Verein.<br>Eine gemeinsame Idee.</h1><p class="lead">Wir halten die Verbindung zwischen Hockey-Nationalteams lebendig. Während der aktiven Zeit und danach.</p></section><section class="section"><div class="editorial-image" role="img" aria-label="Bildplatzhalter: Nationalteams und Generationen bei einer gemeinsamen Begegnung"><span>Raum für eure Bilder</span><small>Gemeinsame Begegnung · Querformat</small></div></section>${vision2030()}<section class="section"><h2>Aus einer Idee wird eine Institution.</h2><p class="lead">EINTRIKOT ist aus der DHB Alumni Familie entstanden. Wir geben dieser gewachsenen Gemeinschaft einen verlässlichen, unabhängigen Rahmen.</p><p>Das Netzwerk soll langfristig bestehen – unabhängig davon, welche Personen beim Deutschen Hockey-Bund Verantwortung tragen. Als eigenständiger Verein schaffen wir klare Zuständigkeiten und bewahren die Verbindung über Generationen hinweg.</p><p>Ein Vorbild sind die niederländischen De Batavieren, die seit 1937 Hockeyspieler zusammenbringen. Auch EINTRIKOT soll eine bleibende Institution für den deutschen Hockeyleistungssport werden.</p><h2>Unsere Werte</h2><div class="info-grid"><article><h3>Gemeinschaft</h3><p>Das Nationaltrikot verbindet Jugend, Aktive, Ehemalige und Masters. Gemeinsame Erfahrungen schaffen Nähe über die eigene Mannschaft hinaus.</p></article><article><h3>Verantwortung</h3><p>Erfahrung und Möglichkeiten weitergeben: Wir möchten die nächste Generation unterstützen und zur Zukunft des deutschen Hockeys beitragen.</p></article><article><h3>Unabhängigkeit</h3><p>Eigenständig, transparent und von unseren Mitgliedern getragen. Unser Handeln dient dem Hockeyleistungssport.</p></article></div></section><section class="section info-grid"><article><h2>Was ist EINTRIKOT?</h2><p>Ein gemeinnütziger Verein und generationsübergreifendes Netzwerk für aktuelle und ehemalige Hockey-Nationalspielerinnen und Nationalspieler. Jugend, Damen, Herren, Masters und die begleitenden Staffteams gehören zusammen.</p></article><article><h2>Was tun wir?</h2><p>Wir ermöglichen Austausch und Begegnungen, geben Erfahrungen weiter und fördern die nächste Generation im Hockey.</p></article><article><span class="micro">Vision</span><h2>Eine tragende Säule für den Leistungssport.</h2><p>Wir bauen ein generationsübergreifendes Netzwerk auf, das sich mittel- bis langfristig zu einer tragenden Säule für die Finanzierung des Leistungssports im Deutschen Hockey-Bund (DHB) entwickelt.</p></article><article><span class="micro">Mission</span><h2>Verbinden. Weitergeben. Fördern.</h2><p>Wir fördern die Nachwuchsarbeit und die Nationalmannschaften des DHB durch gebündelte Erfahrung, Wissen und Ressourcen. Wir initiieren und unterstützen Projekte, stärken die finanzielle Basis des DHB und schaffen mit gemeinsamen Aktivitäten ein starkes Gemeinschaftsgefühl.</p></article><article><h2>Wie finanzieren wir uns?</h2><p>Mitgliedsbeiträge tragen die Vereinsarbeit. Spenden und ehrenamtliches Engagement ermöglichen zusätzliche Vorhaben.</p><p class="only-demo">Konkrete Beiträge, Mittelverwendung und Satzungsangaben werden mit dem Vorstand abgestimmt. Die Verwaltung bleibt in MeinVerein.</p></article><article><h2>Unser Modell</h2><p>Rein ins Trikot. Im Trikot. Raus aus dem Trikot. Drei Phasen, eine Gemeinschaft – Mitgliedschaft ist schon im Jugendnationalteam möglich.</p><a class="text-link" href="#konzept">Die Trikotphasen ↗</a></article></section><section class="section quote"><h2>Unterstützung hat viele Formen.</h2><div class="support-links"><a href="#beitritt">Mitglied werden ↗</a><a href="#unterstuetzen">Unsere Arbeit unterstützen ↗</a><a href="#spenden">Spenden ↗</a></div></section><section class="section"><h2>Wer dahintersteht.</h2><p>Vorstand und Beirat geben dem Verein Richtung und gestalten seine Arbeit.</p><a class="text-link" href="#menschen">Die Menschen kennenlernen ↗</a></section></main>${footer()}`}
function people(){return `${header()}<main id="main"><section class="section page-intro"><h1>Die Menschen<br>hinter EINTRIKOT.</h1><p class="lead">Von Mitgliedern getragen. Ehrenamtlich gestaltet.</p></section><section class="section"><h2>Unsere Gründungsmitglieder</h2><p>Sie haben den deutschen Hockeysport über viele Jahre geprägt. Gemeinsam übernehmen sie Verantwortung über die eigene Karriere hinaus.</p><div class="founder-grid">${['Andreas Arntzen','Björn Emmerling','Natascha Keller','Fanny Rinne','Uschi Schmitz','Markus Weise','Wibke Weisel'].map(name=>`<article class="founder"><div class="founder-photo" role="img" aria-label="Porträtplatzhalter: ${name}"><span>${name.split(' ').map(n=>n[0]).join('')}</span></div><h3>${name}</h3></article>`).join('')}</div></section><section class="section people-board"><h2>Der Vorstand</h2><p>Der Vorstand arbeitet ehrenamtlich und gestaltet die Entwicklung von EINTRIKOT.</p><div class="board-list">${[['Björn Emmerling','1. Vorsitzender','Björn verantwortet die strategische Ausrichtung und Repräsentation des Vereins. Als Weltmeister 2002 und 2006 kennt er die Kraft einer Mannschaft und bringt diese Erfahrung in die Entwicklung unseres Netzwerks ein.'],['Markus Weise','2. Vorsitzender','Markus bringt seine Expertise aus Jahrzehnten im Welthockey in die sportliche Leitung ein. Als dreifacher Olympiasieger-Trainer kennt er die Voraussetzungen für nachhaltigen Erfolg im Leistungssport.'],['Fanny Rinne','Schatzmeisterin','Fanny sorgt für solide Finanzen und transparente Mittelverwendung. Die ehemalige Kapitänin und Olympiasiegerin verbindet ihre Erfahrung im Nationalteam mit der Verantwortung für eine verlässliche finanzielle Basis des Vereins.']].map(([name,role,description])=>`<article class="board-person"><div class="board-photo" role="img" aria-label="Porträtplatzhalter: ${name}"><span>Porträt folgt</span></div><div><span class="micro">${role}</span><h3>${name}</h3><p>${description}</p></div></article>`).join('')}</div></section><section class="section"><h2>Der Beirat</h2><p>Der Beirat begleitet den Vorstand mit Erfahrung und Perspektiven aus dem Hockeysport.</p><div class="advisory-list"><article class="advisory-person"><div class="advisory-photo" role="img" aria-label="Quadratischer Porträtplatzhalter für den Beirat">Porträt folgt</div><div><h3>Vorstellung folgt</h3><p>Hier stellen wir die Beiratsmitglieder mit ihrem Hintergrund und ihrem Beitrag für EINTRIKOT vor.</p></div></article></div><p class="only-demo">Namen, Porträts und persönliche Kurzvorstellungen des Beirats werden ergänzt, sobald sie vorliegen.</p></section></main>${footer()}`}

function filterSelect(key,label,options){return `<label>${label}<select data-filter="${key}"><option value="">Alle</option>${options.map(x=>`<option ${directoryFilters[key]===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label>`}
function directory(){return shell(`<div class="profile-title"><h1>Menschen, die<br>dein Spiel teilen.</h1><p>Verbindungen über Teams und Generationen.</p></div><div class="directory-tools"><label class="search-label"><span class="sr-only">Mitglieder suchen</span><input id="member-search" type="search" placeholder="Name, Team, U18, Ort oder Beruf suchen" value="${esc(directoryFilters.query)}"></label><button class="button" id="filter-toggle" aria-expanded="false" aria-controls="member-filters">Filter</button></div><div id="member-filters" hidden>${filterSelect('team','Team',['Damen','Herren'])}${filterSelect('age','Altersklasse',['U18','U21','A-Nationalteam'])}${filterSelect('phase','Trikotphase',['Aktuell','Ehemalig'])}${filterSelect('club','Verein',['Testverein Nord','Testverein Süd','Testverein West'])}${filterSelect('job','Beruf / Ausbildung',['Schule','Studium','Sport','Architektur','Medizin'])}${filterSelect('hobbies','Interessen',['Musik','Reisen','Lesen','Laufen'])}<button class="text-reset" id="clear-filters">Zurücksetzen</button></div><p class="only-demo">Nur synthetische Testprofile. Produktiv ausschließlich nach Login und entsprechend der Profilfreigaben.</p><p id="member-count" role="status"></p><div id="member-results"></div>`,'mitglieder')}
function drawMembers(){const el=document.querySelector('#member-results');if(!el)return;const f=directoryFilters;const rows=sampleMembers.filter(m=>(!f.query||f.query.toLocaleLowerCase('de').trim().split(/\s+/).every(q=>[m.name,m.club,m.job,m.team,m.age,m.phase,m.hobbies,m.cityVisibility==='members'?m.city:''].join(' ').toLocaleLowerCase('de').includes(q)))&&['team','age','phase','club','job','hobbies'].every(k=>!f[k]||m[k]===f[k]));document.querySelector('#member-count').textContent=`${rows.length} ${rows.length===1?'Testprofil':'Testprofile'}`;el.innerHTML=rows.length?rows.map(m=>`<a class="member-row" href="#mitglied-${m.id}"><span class="member-avatar" aria-hidden="true">${m.id.toUpperCase()}</span><div><h2>${esc(m.name)}</h2><small>${esc(m.team)} · ${esc(m.age)} · ${esc(m.phase)}${m.cityVisibility==='members'?` · <strong>${esc(m.city)}</strong>`:''}</small></div><span class="member-open">Profil ansehen ↗</span></a>`).join(''):'<p class="empty">Keine passenden Profile. Passe die Suche oder Filter an.</p>'}
function memberDetail(page){const m=sampleMembers.find(m=>page==='mitglied-'+m.id);if(!m)return directory();return shell(`<a class="text-link" href="#mitglieder">← Alle Mitglieder</a><div class="profile-title member-profile-heading" style="margin-top:35px"><div class="profile-portrait" role="img" aria-label="Porträtplatzhalter für ${esc(m.name)}"><span>${esc(m.name.split(' ').map(x=>x[0]).join(''))}</span><small>Profilbild</small></div><h1>${esc(m.name)}</h1>${['board','admin'].includes(previewRole)?`<button class="button" id="edit-member" data-member="${m.id}">Profil bearbeiten</button>`:''}<p>${esc(m.team)} · ${esc(m.age)} · ${esc(m.phase)}</p></div><div class="info-grid">${m.cityVisibility==='members'?`<article><h2>Wohnort</h2><p>${esc(m.city)}</p></article>`:''}<article><h2>Aktueller Verein</h2><p>${esc(m.club)}</p></article><article><h2>Beruf / Ausbildung</h2><p>${esc(m.job)}</p></article><article><h2>Interessen</h2><p>${esc(m.hobbies)}</p></article></div><section class="portal-section"><h2>DHB-Vita</h2><p class="only-demo">Synthetische Beispielstation – produktiv erscheinen hier die freigegebenen Stationen aus dem Profil.</p><article class="vita-entry"><span>${m.phase==='Aktuell'?'Seit 2024':'2008–2012'}</span><div><h3>Spielerin / Spieler</h3><p>DHB · ${esc(m.team)} · ${esc(m.age)}</p></div></article></section><p class="only-demo">Dieses Profil ist frei erfunden. Private Felder werden produktiv auch nicht für Suchtreffer oder Filter ausgewertet.</p>`,'mitglieder')}
function restrictedNewsletter(){return canEdit()?newsletter():shell('<h1>Redaktioneller Bereich</h1><p>Die Newsletter-Gestaltung gehört zur Redaktion. Dieser Arbeitsbereich ist für Redakteure, Vorstand und Administration vorgesehen.</p><p class="only-demo">Über die Rollen-Vorschau oben lässt sich die geplante Ansicht testen. Das ist noch keine serverseitige Zugriffskontrolle.</p>','portal')}
function editorial(){if(!canEdit())return restrictedNewsletter();return shell(`<div class="profile-title"><h1>Redaktion.</h1><p>Ein guter Entwurf. Gemeinsam zur fertigen Ausgabe.</p></div><section class="form-section"><h2>Newsletter</h2><p>KI-Entwurf einlesen → bearbeiten → prüfen → zum Versand freigeben.</p><p class="only-demo">Diesen Ablauf bauen wir später aus. Aktuell werden keine Entwürfe importiert oder Newsletter versendet.</p></section>`,'redaktion')}

function administration(){if(!['board','admin'].includes(previewRole))return shell('<h1>Administration</h1><p>Dieser Bereich ist für die technische Administration vorgesehen.</p>','portal');return shell(`<div class="profile-title"><h1>Administration.</h1><p>Einträge pflegen. Änderungen nachvollziehen.</p></div><section class="form-section"><h2>Kennzahlen der Website</h2><form id="metrics-form" class="form-grid">${Object.entries(metricLabels).map(([key,label])=>`<label class="field">${label}<input name="${key}" type="number" min="0" step="${key==='donations'?'0.01':'1'}" required value="${metrics[key]}"></label>`).join('')}<button class="button solid" type="submit">Kennzahlen speichern</button></form><p>Länderspiele werden automatisch aus den Profilangaben summiert und sind hier nicht manuell überschreibbar.</p><p class="only-demo">Bestätigte Ausgangswerte. Änderungen gelten in dieser Vorschau nur für die Sitzung.</p></section><section class="portal-section"><a class="text-link" href="#protokoll">Änderungsprotokoll öffnen ↗</a></section>`,'admin')}
function auditMarkup(){return audit.length?audit.map(a=>`<article class="audit-row"><strong>${esc(a.when)} · Verwaltungsansicht</strong><p>${esc(a.name)} · ${esc(a.field||'Aktueller Verein')}: ${esc(a.before)} → ${esc(a.after)}</p><small>Grund: ${esc(a.reason)}</small></article>`).join(''):'<p class="empty">Noch keine Änderungen in dieser Sitzung.</p>'}
function bindExistingNew(){document.querySelector('#metrics-form')?.addEventListener('submit',e=>{e.preventDefault();let changed=0;for(const key of Object.keys(metrics)){const value=Number(e.target.elements[key].value);if(!Number.isFinite(value)||value<0)return;if(value!==metrics[key]){audit.unshift({when:new Date().toLocaleString('de-DE'),name:'Website-Kennzahl',field:metricLabels[key],before:metrics[key],after:value,reason:'Kennzahl über Admin-Vorschau aktualisiert'});metrics[key]=value;changed++}}if(document.querySelector('#audit-list'))document.querySelector('#audit-list').innerHTML=auditMarkup();toast(changed?'Kennzahlen aktualisiert und protokolliert.':'Keine Kennzahl geändert.')});document.querySelector('#member-search')?.addEventListener('input',e=>{directoryFilters.query=e.target.value;drawMembers()});document.querySelector('#filter-toggle')?.addEventListener('click',e=>{const f=document.querySelector('#member-filters');f.hidden=!f.hidden;e.currentTarget.setAttribute('aria-expanded',String(!f.hidden))});document.querySelectorAll('[data-filter]').forEach(el=>el.addEventListener('change',()=>{directoryFilters[el.dataset.filter]=el.value;drawMembers()}));document.querySelector('#clear-filters')?.addEventListener('click',()=>{Object.keys(directoryFilters).forEach(k=>directoryFilters[k]='');document.querySelector('#member-search').value='';document.querySelectorAll('[data-filter]').forEach(e=>e.value='');drawMembers()});drawMembers();document.querySelectorAll('[data-work]').forEach(b=>b.addEventListener('click',()=>showNotice('Redaktioneller Ablauf','Themen werden gesammelt und geprüft. Die konkrete Ausgabe wird vom Vorstand freigegeben. Google Workspace und MailPoet werden erst in WordPress angebunden; aus dieser Vorschau wird nichts veröffentlicht oder versendet.')));const af=document.querySelector('#admin-edit');if(af){af.elements.member.addEventListener('change',()=>{af.elements.club.value=sampleMembers.find(m=>m.id===af.elements.member.value).club});af.addEventListener('submit',e=>{e.preventDefault();const m=sampleMembers.find(m=>m.id===af.elements.member.value);const after=af.elements.club.value.trim();if(!after)return;if(after===m.club){toast('Keine Änderung am Profil.');return}audit.unshift({when:new Date().toLocaleString('de-DE'),name:m.name,before:m.club,after,reason:af.elements.reason.value.trim()});m.club=after;if(document.querySelector('#audit-list'))document.querySelector('#audit-list').innerHTML=auditMarkup();af.elements.reason.value='';toast('Teständerung im Sitzungsprotokoll erfasst.')})}}
function setupRolePreview(){const nav=document.querySelector('.review nav');nav.querySelector('a[href="#newsletter"]')?.remove();nav.insertAdjacentHTML('beforeend','<label class="role-preview">Ansicht <select id="role-preview"><option value="member">Mitglied</option><option value="editor">Redaktion</option><option value="board">Vorstand</option><option value="admin">Admin</option></select></label><a id="editorial-shortcut" href="#redaktion" hidden>Redaktion</a><a id="admin-shortcut" href="#admin" hidden>Admin</a>');document.querySelector('#role-preview').addEventListener('change',e=>{previewRole=e.target.value;document.querySelector('#editorial-shortcut').hidden=!canEdit();document.querySelector('#admin-shortcut').hidden=!['board','admin'].includes(previewRole);render()})}
// Public support destinations are not active until MeinVerein/recipient links are approved.
window.addEventListener('hashchange',()=>{if(['unterstuetzen','spenden'].includes(location.hash.slice(1))){showNotice(location.hash==='#spenden'?'EINTRIKOT unterstützen':'Partner oder Sponsor werden','Der passende Kontakt beziehungsweise MeinVerein-Link wird nach Freigabe hinterlegt. In dieser Vorschau wird keine Zahlung oder Anfrage ausgelöst.')}});
function dashboard(){return shell(`<section class="welcome"><h1>Dein Netzwerk.</h1><p>Finde Menschen, die dein Spiel teilen.</p></section><section class="network-entry"><h2>Wen möchtest du wiederfinden?</h2><p>Jugend, Damen, Herren und Ehemalige. Alle an einem Ort.</p><a class="button solid" href="#mitglieder">Mitglieder entdecken ↗</a></section><div class="portal-grid compact-home"><section><h2>Vereinsinfos</h2><article class="news-piece"><h3>Willkommen bei EINTRIKOT</h3><p>Dein Profil verbindet dich mit unserem Netzwerk. Ergänze, was du teilen möchtest.</p><a class="text-link" href="#profil">Mein Profil ansehen ↗</a></article><a class="text-link" href="#mitglieder-news">Alle Vereinsinfos ↗</a></section><section><h2>Was möchtest du bewegen?</h2><p>Eine Idee teilen, dich einbringen oder EINTRIKOT zusätzlich fördern.</p><a class="text-link" href="#services">Zum Service ↗</a></section></div>`,'portal')}
let accountPhoto='';
let fundingRequest=null;
function localDate(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function ageFromDate(value){if(!value||value>localDate())return null;const [y,m,d]=value.split('-').map(Number);const now=new Date();return now.getFullYear()-y-((now.getMonth()+1<m||(now.getMonth()+1===m&&now.getDate()<d))?1:0)}
function accountMenu(){return `<header class="account-header"><details class="account-menu"><summary><span class="account-avatar">${accountPhoto?`<img src="${accountPhoto}" alt="">`:'TM'}</span><span>Testmitglied</span><span aria-hidden="true">⌄</span></summary><nav aria-label="Mein Konto"><a href="#profil">Mein Profil bearbeiten</a><button type="button" id="logout">Ausloggen</button><small>Vorschau-Konto</small></nav></details></header>`}
function fundingPage(){return shell(`<a class="text-link" href="#services">← Service</a><div class="profile-title"><h1>EINTRIKOT<br>zusätzlich fördern.</h1><p>Dein jährlicher Beitrag kann mehr möglich machen.</p></div>${fundingRequest?`<section class="funding-status"><h2>Anfrage vorgemerkt</h2><p>${esc(fundingRequest.amount)} € jährlich · ab ${esc(fundingRequest.date)}</p><p>Status: Prüfung durch Vorstand / Schatzmeisterin ausstehend.</p><small>Nur diese Vorschau-Sitzung. Keine Übertragung an MeinVerein.</small></section>`:`<form id="funding-form" class="contact-form"><label class="field">Freiwilliger Betrag pro Jahr<select name="amount"><option value="50">50 €</option><option value="100">100 €</option><option value="150">150 €</option><option value="custom">Individueller Betrag</option></select></label><label class="field" id="custom-amount" hidden>Individueller Jahresbetrag in Euro<input name="custom" type="number" min="0.01" step="0.01" disabled></label><label class="field">Gewünschter Beginn<input name="effective" type="date" min="${localDate()}" required></label><label class="check"><input name="confirm" type="checkbox" required><span>Ich beantrage diesen jährlich wiederkehrenden freiwilligen Betrag zusätzlich zum Mitgliedsbeitrag. Erst nach Prüfung und Übernahme in MeinVerein wird die Änderung verbindlich.</span></label><p class="only-demo">Lokale Vorschau: kein Versand, keine Zahlung und keine Änderung in MeinVerein.</p><button class="button solid">Anfrage vormerken</button></form>`}`,'services')}
function bindNew(){bindExistingNew();bindRefinements();bindCalendar();bindMasterData();applyHeroImages();const pf=document.querySelector('#profile-form');if(pf){const updateAge=()=>{const age=ageFromDate(pf.elements.birthday.value);document.querySelector('#age-preview').textContent=age===null?'Noch kein Geburtsdatum angegeben.':`${age} Jahre · Sichtbarkeit separat wählbar`;};updateAge();pf.elements.birthday.addEventListener('input',updateAge);pf.addEventListener('reset',()=>{accountPhoto='';document.querySelector('.account-avatar').textContent='TM';setTimeout(()=>{updateAge();document.querySelector('#avatar').hidden=true;},0)});document.querySelector('#prepare-funding').addEventListener('click',()=>{savedProfile=[...new FormData(pf)].filter(([,v])=>typeof v==='string')});if(accountPhoto){document.querySelector('#avatar').src=accountPhoto;document.querySelector('#avatar').hidden=false}document.querySelector('#avatar-file').addEventListener('change',()=>{const img=document.querySelector('#avatar');if(!img.hidden){accountPhoto=img.src;document.querySelector('.account-avatar').innerHTML=`<img src="${accountPhoto}" alt="">`}})}document.querySelector('#logout')?.addEventListener('click',()=>{savedProfile=null;accountPhoto='';fundingRequest=null;previewRole='member';document.querySelector('#role-preview').value='member';document.querySelector('#editorial-shortcut').hidden=true;document.querySelector('#admin-shortcut').hidden=true;location.hash='login';toast('Vorschau verlassen. Profileingaben gelöscht. Echter Logout folgt mit WordPress.')});const ff=document.querySelector('#funding-form');if(ff){ff.elements.amount.addEventListener('change',()=>{const custom=ff.elements.amount.value==='custom';document.querySelector('#custom-amount').hidden=!custom;ff.elements.custom.disabled=!custom;ff.elements.custom.required=custom});ff.addEventListener('submit',e=>{e.preventDefault();if(!ff.reportValidity())return;const amount=Number(ff.elements.amount.value==='custom'?ff.elements.custom.value:ff.elements.amount.value);if(!Number.isFinite(amount)||amount<=0)return;fundingRequest={amount,date:ff.elements.effective.value};render()})}}
function bindRefinements(){
const counters=document.querySelectorAll('.metrics strong');if(counters.length){const values=[metrics.members,metrics.donations,totalCaps(),metrics.generations];const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const observer=new IntersectionObserver(entries=>{for(const entry of entries){if(!entry.isIntersecting)continue;observer.unobserve(entry.target);const index=[...counters].indexOf(entry.target),value=values[index],start=performance.now();const frame=now=>{if(!entry.target.isConnected)return;const progress=reduced?1:Math.min((now-start)/1400,1);entry.target.textContent=Math.round(value*(1-Math.pow(1-progress,3))).toLocaleString('de-DE')+(index===1?' €':'');if(progress<1)requestAnimationFrame(frame)};requestAnimationFrame(frame)}},{threshold:.3});counters.forEach((el,i)=>{if(values[i]===null){el.textContent='—';el.setAttribute('aria-label','Noch keine Angaben');return}el.setAttribute('aria-label',values[i].toLocaleString('de-DE')+(i===1?' Euro':''));el.textContent='0'+(i===1?' €':'');observer.observe(el)})}
document.querySelector('#edit-member')?.addEventListener('click',e=>{if(!['board','admin'].includes(previewRole))return;const m=sampleMembers.find(x=>x.id===e.currentTarget.dataset.member);const area=document.querySelector('.info-grid');area.innerHTML=`<form id="member-inline-edit" class="contact-form"><h2>Profil bearbeiten</h2>${[['name','Name'],['city','Wohnort'],['club','Verein'],['team','Team'],['age','Altersklasse'],['phase','Trikotphase'],['job','Beruf / Ausbildung'],['hobbies','Interessen']].map(([key,label])=>`<label class="field">${label}<input name="${key}" value="${esc(m[key]||'')}" maxlength="120" required></label>`).join('')}<label class="field">Grund der Änderung<textarea name="reason" required minlength="5"></textarea></label><p class="only-demo">Nur Testprofil. Änderungen werden für diese Sitzung protokolliert.</p><button class="button solid">Änderungen speichern</button><button class="button" type="button" id="cancel-edit">Abbrechen</button></form>`;document.querySelector('#cancel-edit').onclick=render;document.querySelector('#member-inline-edit').addEventListener('submit',event=>{event.preventDefault();if(!['board','admin'].includes(previewRole))return;const data=new FormData(event.target);for(const key of ['name','city','club','team','age','phase','job','hobbies']){const value=data.get(key).trim();if(value!==m[key]){audit.unshift({when:new Date().toLocaleString('de-DE'),name:m.name,field:key,before:m[key],after:value,reason:data.get('reason')});m[key]=value}}render();toast('Testprofil aktualisiert und protokolliert.')})})}
// Demonstration content only; WordPress will supply dated, published posts.
const newsPosts=[
{slug:'willkommen',type:'Beitrag',title:'Ein neuer Ort für unser Netzwerk',intro:'Hier bekommt der Beitrag zum neuen Mitgliederportal seinen Platz.',color:'blue'},
{slug:'generationen',type:'Interview',title:'Was uns über Generationen verbindet',intro:'Platz für ein freigegebenes Gespräch aus der Community.',color:'pink'},
{slug:'nachwuchs',type:'Geschichte',title:'Gemeinsam für die nächste Generation',intro:'Platz für eine Geschichte aus der Vereinsarbeit.',color:'green'},
{slug:'begegnungen',type:'Beitrag',title:'Wiedersehen. Weiterdenken.',intro:'Platz für einen Rückblick auf eine gemeinsame Begegnung.',color:'gold'}];
function newsCards(posts){return `<div class="news-cards">${posts.map(p=>`<article class="news-card"><a href="#beitrag-${p.slug}"><div class="news-cover ${p.color}"><span>${p.type}</span><small>Beitragsbild · Bildplatzhalter</small></div><small>Redaktioneller Platzhalter</small><h3>${p.title}</h3><p>${p.intro}</p><span class="text-link">Beitrag ansehen ↗</span></a></article>`).join('')}</div>`}
function newsArchive(){return `${header()}<main id="main"><section class="section page-intro"><span class="micro">Aus dem Netzwerk</span><h1>News.</h1><p class="lead">Geschichten, Interviews und Beiträge von EINTRIKOT.</p></section><section class="section news-archive">${newsCards(newsPosts)}<p class="only-demo">Gestaltungsbeispiele, keine veröffentlichten Geschichten. Produktiv erscheinen alle freigegebenen Beiträge, neueste zuerst.</p></section></main>${footer()}`}
function newsArticle(route){const p=newsPosts.find(p=>route==='beitrag-'+p.slug);if(!p)return newsArchive();return `${header()}<main id="main" class="section article-page"><a class="text-link" href="#news">← Alle News</a><p class="micro">${p.type} · Redaktioneller Platzhalter</p><h1>${p.title}</h1><p class="lead">${p.intro}</p><p>Hier wird der vollständige, freigegebene Beitrag im WordPress-Editor gepflegt. Text, Bilder und gegebenenfalls Interviewfragen lassen sich unabhängig vom Theme bearbeiten.</p><p class="only-demo">Für diese Vorschau wurden keine Interviews oder Vereinsereignisse erfunden.</p></main>${footer()}`}
const engagementMedia={growth:null,share:null,people:null};
function engagementPicture(key){const media=engagementMedia[key];return media?.url?`<img class="engagement-image" src="${esc(media.url)}" alt="${esc(media.alt||'')}" loading="lazy">`:''}
function engagementPage(){return `${header()}<main id="main"><section class="section page-intro"><h1>Gemeinsam etwas<br>möglich machen.</h1><p class="lead">Wir bündeln Erfahrung, Wissen und Ressourcen für die Nachwuchsarbeit und die Nationalmannschaften des DHB.</p></section><section class="section info-grid engagement-topics">${[['growth','Nachwuchs fördern','Wir wollen dort unterstützen, wo konkrete Mittel fehlen: bei Trainingsmaterialien, medizinischen Hilfsmitteln, Ausrüstung oder ergänzenden Lehrgängen. Gemeinsam mit den Teams identifizieren wir sinnvolle Vorhaben.'],['share','Erfahrung weitergeben','In unserer Community steckt Wissen aus dem Spitzensport und dem Leben darüber hinaus. Mentoring und persönliche Kontakte sollen jungen Spielerinnen und Spielern Orientierung geben – auch bei Ausbildung, Studium und Berufseinstieg.'],['people','Begegnungen schaffen','Gemeinsame Aktivitäten verbinden aktive und ehemalige Nationalteams, Masters und Staff. Daraus können neue Kontakte, gegenseitige Unterstützung und gemeinsame Projekte entstehen.']].map(([i,t,p])=>`<article data-image-slot="${i}">${engagementPicture(i)}${icon(i)}<h2>${t}</h2><p>${p}</p></article>`).join('')}</section><section class="section"><h2>Aus der Community.<br>Für die Zukunft.</h2><p>Mitgliedsbeiträge, Spenden und gezielte Kampagnen sollen die Förderung tragen. Unser Anspruch: Mittel gezielt einsetzen und ihre Verwendung transparent machen.</p><a class="button" href="#partner">Unsere Arbeit unterstützen ↗</a></section></main>${footer()}`}

function thanks(){return `<section class="section thanks"><h2>Von Mitgliedern<br>möglich gemacht.</h2><p>Danke für euren Beitrag zu EINTRIKOT.</p><div class="info-grid"><article><h3>Andreas Arntzen</h3><p>Für seine Spende zur Deckung der administrativen Aufwände.</p></article><article><h3>Kathrin Jacobsen</h3><p>Für Logo, Farben und Design von EINTRIKOT.</p></article><article><h3>Axel Kaste</h3><p>Für die Bilder und seinen besonderen Einsatz als Bildlieferant.</p></article></div></section>`}
function partnerPage(){return `${header()}<main id="main"><section class="section page-intro"><h1>Gemeinsam für den deutschen Hockeyleistungssport.</h1><p class="lead">EINTRIKOT ist ein gemeinnütziger Verein. Mitgliedschaft, ehrenamtliches Engagement und Spenden tragen unsere Arbeit.</p><a class="button" href="#spenden">Mit einer Spende unterstützen ↗</a></section>${thanks()}</main>${footer()}`}
const calendarEntries=[{title:'WM-Titel 2006 in Mönchengladbach',date:'2006-09-17',type:'Jahrestag',annual:true}];
function occurrence(entry,reference){let date=entry.date;if(entry.annual){date=reference.slice(0,4)+entry.date.slice(4);if(date<reference)date=(Number(reference.slice(0,4))+1)+entry.date.slice(4)}return date}
function calendarList(){const today=localDate();const rows=[...calendarEntries];if(savedProfile?.some(([k])=>k==='birthday_notice')){const date=savedProfile.find(([k])=>k==='birthday')?.[1];if(date)rows.push({title:'Geburtstag: Testmitglied',date,type:'Geburtstag',annual:true})}return rows.map(e=>({...e,next:occurrence(e,today)})).filter(e=>e.next>=today).sort((a,b)=>a.next.localeCompare(b.next))}
function clubInfos(){const horizon=new Date();horizon.setDate(horizon.getDate()+30);const limit=`${horizon.getFullYear()}-${String(horizon.getMonth()+1).padStart(2,'0')}-${String(horizon.getDate()).padStart(2,'0')}`;const events=calendarList().filter(e=>e.next<=limit);return shell(`<h1>Vereinsinfos.</h1><p>Was uns gerade verbindet. Intern für unsere Mitglieder.</p>${canEdit()?'<a class="button" href="#kalender">EINTRIKOT-Kalender pflegen ↗</a>':''}<section class="portal-section"><h2>In den nächsten 30 Tagen</h2>${events.length?events.map(e=>`<article class="news-piece"><small>${esc(e.next.split('-').reverse().join('.'))} · ${esc(e.type)}</small><h3>${esc(e.title)}</h3>${e.type==='Jahrestag'?`<p>${Number(e.next.slice(0,4))-Number(e.date.slice(0,4))}. Jahrestag</p>`:''}</article>`).join(''):'<p>Aktuell keine anstehenden Kalenderhinweise.</p>'}</section><p class="only-demo">Automatisch aus dem Vorschau-Kalender. Keine E-Mails. Neue Einträge bleiben nur bis zum Neuladen erhalten.</p>`,'mitglieder-news')}
function calendarPage(){if(!canEdit())return shell('<h1>Kalenderpflege</h1><p>Dieser Bereich ist für Redaktion, Vorstand und Admin vorgesehen.</p>','mitglieder-news');return shell(`<a class="text-link" href="#mitglieder-news">← Vereinsinfos</a><h1>EINTRIKOT-Kalender.</h1><p>Einmal eintragen. Rechtzeitig in den Vereinsinfos sichtbar.</p><form id="calendar-form" class="contact-form"><label class="field">Titel<input name="title" required maxlength="160"></label><label class="field">Datum des Ereignisses<input name="date" type="date" required></label><label class="field">Art<select name="type"><option>Termin</option><option>Jahrestag</option></select></label><label class="check"><input name="annual" type="checkbox"><span>Jährlich wiederholen</span></label><p>Freigegebene Geburtstage werden aus den Profilen abgeleitet. Keine doppelte Geburtstagsliste nötig.</p><p class="only-demo">Nur erfundene Testtermine eingeben. Speicherung gilt nur für diese Vorschau-Sitzung.</p><button class="button solid">Eintrag speichern</button></form><section class="portal-section"><h2>Gespeicherte Ereignisse</h2>${calendarList().map(e=>`<p>${esc(e.next)} · ${esc(e.title)}</p>`).join('')}</section>`,'mitglieder-news')}
function bindCalendar(){document.querySelector('#calendar-form')?.addEventListener('submit',e=>{e.preventDefault();if(!canEdit())return;const f=e.target;const title=f.elements.title.value.trim();if(!title)return;calendarEntries.push({title,date:f.elements.date.value,type:f.elements.type.value,annual:f.elements.annual.checked});render();toast('Kalendereintrag für diese Sitzung gespeichert.')})}
function masterDataPage(){return shell(`<a class="text-link service-back" href="#services">← Service</a><h1>Stammdaten ändern.</h1><p>Adresse, Kontakt oder Bankverbindung aktuell halten.</p><form id="master-data-form" class="contact-form"><label class="field">Was möchtest du ändern?<select name="kind"><option value="address">Postanschrift</option><option value="contact">Kontaktdaten</option><option value="bank">Bankverbindung</option></select></label><div id="master-fields"></div><p class="only-demo">Vorschau: ausschließlich erfundene Daten verwenden. Kein Versand, keine Speicherung in MeinVerein.</p><button class="button solid" id="master-submit">Änderungsanfrage prüfen</button></form>`,'services')}
function bindMasterData(){const form=document.querySelector('#master-data-form');if(!form)return;const draw=()=>{const kind=form.elements.kind.value;document.querySelector('#master-fields').innerHTML=kind==='bank'?'<h2>Bankwechsel</h2><p>Bankverbindung und SEPA-Mandat werden ausschließlich in MeinVerein gepflegt. Bitte hier keine IBAN oder Bankunterlagen eingeben.</p><p>Über diesen Service kannst du einen sicheren Änderungsweg bei der zuständigen Mitgliederverwaltung anfordern.</p>':kind==='address'?'<label class="field">Straße und Hausnummer<input name="street" required maxlength="150"></label><label class="field">Postleitzahl<input name="postal" required maxlength="20"></label><label class="field">Ort<input name="city" required maxlength="100"></label><label class="field">Land<input name="country" required maxlength="80"></label>':'<label class="field">Neue E-Mail-Adresse<input name="email" type="email" maxlength="254"></label><label class="field">Neue Telefonnummer<input name="phone" type="tel" maxlength="40"></label>';document.querySelector('#master-submit').textContent=kind==='bank'?'Sicheren Änderungsweg anfordern':'Änderungsanfrage prüfen'};draw();form.elements.kind.addEventListener('change',draw);form.addEventListener('submit',e=>{e.preventDefault();if(form.elements.kind.value==='contact'&&!form.elements.email.value.trim()&&!form.elements.phone.value.trim()){showNotice('Angabe fehlt','Bitte mindestens eine neue Kontaktangabe eintragen.');return}showNotice('Änderungsanfrage vorbereitet','In WordPress geht die Anfrage an die zuständige Mitgliederverwaltung. Erst deren Übernahme aktualisiert MeinVerein. Diese Vorschau hat nichts übertragen.')})}
// Media URLs come from WordPress attachment fields in production, never from text HTML.
const heroMedia={website:null,verein:null,engagement:null,news:null,partner:null,menschen:null};
function applyHeroImages(){const media=heroMedia[current];const hero=document.querySelector('main .hero,main .page-intro');if(!hero)return;hero.dataset.heroImageSlot=current;if(!media?.url)return;const img=document.createElement('img');img.className='hero-background';img.src=media.url;img.alt=media.alt||'';img.style.objectPosition=media.position||'center';hero.prepend(img);hero.classList.add('has-hero-image')}
function vision2030(){return `<section class="vision-2030" aria-labelledby="vision-${current==='verein'?'verein':'start'}"><h2 id="vision-${current==='verein'?'verein':'start'}">Vision 2030</h2><p>Bis 2030 ist Eintrikot eine starke, selbsttragende Community, die alle deutschen Hockey Nationalteams finanziell, strukturell und persönlich unterstützt.</p></section>`}
function totalCaps(){const raw=[...sampleMembers.map(m=>m.caps),savedProfile?.find(([key])=>key==='caps')?.[1]];const valid=raw.filter(v=>v!==undefined&&v!==null&&String(v).trim()!==''&&/^\d+$/.test(String(v))&&Number.isSafeInteger(Number(v))).map(Number);return valid.length?valid.reduce((sum,n)=>sum+n,0):null}
setupRolePreview();render();
